1	const PROCESSING_FEE = 5;
2	
3	export type Item = {
4	  type: string;
5	  material?: string;
6	  enchantment?: number;
7	  cursed?: boolean;
8	};
9	
10	export type Step = {
11	  op: string;
12	  items: Item[];
13	};
14	
15	export type Scenario = {
16	  customer: { yearsWithMHPCO: number };
17	  steps: Step[];
18	};
19	
20	export type StepResult = {
21	  premium: number;
22	};
23	
24	export type ScenarioResults = {
25	  results: StepResult[];
26	};
27	
28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	  moonstone: 25,
35	};
36	
37	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
38	
39	// Percentages are applied as `amount * percent / 100` rather than
40	// `amount * 1.percent`, so that integer amounts stay exact: 100 * 1.1 is
41	// 110.00000000000001 in binary floating point, while 100 * 10 / 100 is 10.
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];
46	
47	const withFirstInsuranceSurcharge = (base: number): number =>
48	  base + percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
49	
50	const BLOCK_SIZE = 3;
51	const BLOCK_BASE_PREMIUM = 60;
52	
53	const groupByType = (items: Item[]): Item[][] => {
54	  const groups = new Map<string, Item[]>();
55	  for (const item of items) {
56	    const group = groups.get(item.type) ?? [];
57	    group.push(item);
58	    groups.set(item.type, group);
59	  }
60	  return [...groups.values()];
61	};
62	
63	// A building block of exactly 3 alike components is offered at a flat rate.
64	const groupBasePremium = (group: Item[]): number => {
65	  if (group.length === BLOCK_SIZE) return BLOCK_BASE_PREMIUM;
66	  return group.reduce((total, item) => total + basePremium(item), 0);
67	};
68	
69	const itemsBasePremium = (items: Item[]): number =>
70	  groupByType(items).reduce(
71	    (total, group) => total + groupBasePremium(group),
72	    0,
73	  );
74	
75	const itemsPremium = (items: Item[]): number =>
76	  withFirstInsuranceSurcharge(itemsBasePremium(items));
77	
78	// Amounts are rounded in the MHPCO's favor: premiums round up.
79	const roundPremium = (amount: number): number => Math.ceil(amount);
80	
81	const quote = (step: Step): StepResult => ({
82	  premium: roundPremium(PROCESSING_FEE + itemsPremium(step.items)),
83	});
84	
85	export const runScenario = (scenario: Scenario): ScenarioResults => ({
86	  results: scenario.steps.map(quote),
87	});
